/// <reference types="node" />
import { getMigrations } from 'better-auth/db/migration';
import { createAuth } from '../src/auth/auth.js';

/** Header of the committed migration file; the rest is Better Auth's own compiled SQL. */
export const MIGRATION_HEADER =
  '-- Better Auth schema for KP-Web sign-in (#127). Generated by scripts/generate-auth-migration.ts; do not edit by hand.\n';

/**
 * The SQL Better Auth plans for our auth config on an empty SQLite database. Node only (uses node:sqlite);
 * the Worker never imports this module.
 */
export async function authMigrationSql(): Promise<string> {
  const { DatabaseSync } = await import('node:sqlite');
  const auth = createAuth({ DB: new DatabaseSync(':memory:'), BETTER_AUTH_SECRET: 'x'.repeat(32) });
  const { compileMigrations } = await getMigrations(auth.options);
  const sql = (await compileMigrations()).trim();
  return MIGRATION_HEADER + sql + (sql.endsWith(';') ? '' : ';') + '\n';
}
